with gaps as (select *, case when started_at - lag(started_at) over (partition by device order by started_at, id) > interval '7' day then 1 else 0 end as session_start_flag from sessions), islands as (select id, device, started_at, sum(session_start_flag) over (partition by device order by started_at, id rows between unbounded preceding and current row) as session_id from gaps) select id, device from islands order by device
